// Helper function to count vowels
function CountVowels(s: string): int
    requires s != null
    ensures 0 <= CountVowels(s) <= |s| // count is non-negative and at most the length of the string
{
    var count := 0;
    var i := 0;
    while i < |s|
        invariant 0 <= i <= |s|
        invariant 0 <= count <= i // count of vowels does not exceed the current index
    {
        if (s[i] == 'a' || s[i] == 'e' || s[i] == 'i' || s[i] == 'o' || s[i] == 'u' ||
            (i == |s| - 1 && (s[i] == 'y' || s[i] == 'Y'))) {
            count := count + 1;
        }
        i := i + 1;
    }
    return count;
}
